 if not abs(r-s)<=d<=r+s:return []
 x=(r*r-s*s+d*d)/(2*d); h=math.sqrt(max(0,r*r-x*x)); u=[(b[i]-a[i])/d for i in range(2)]
 return [[a[0]+x*u[0]+v*h*-u[1],a[1]+x*u[1]+v*h*u[0]] for v in [-1,1]]
def geom(pos,radii):
 for j,r in enumerate(radii):
