def color(pos,rs,N):
 conflicts=[]
 for j in range(9):
  for k in range(j):
   if (k,j) in meshes:continue
   if owners[k]==owners[j] or dist(pos[owners[k]],pos[owners[j]])<rs[k]+rs[j]+.10-1e-9:conflicts.append((k,j))
 # four meshing groups plus escape wheel
 groups=[(0,1),(2,3),(4,5),(6,7),(8,)]
 for vals in itertools.product(range(N),repeat=5):
  if vals[0]>=N-1:continue
  lev=[0]*9
  for g,v in zip(groups,vals):
   for j in g:lev[j]=v
  if any(({lev[a],lev[a]+1} if a==0 else {lev[a]}) & ({lev[b],lev[b]+1} if b==0 else {lev[b]}) for a,b in conflicts):continue
