for N in [3,4,5]:
 for w,p,z,q in pairs:
  for m,n in itertools.product(mods,repeat=2):
   for t in circles(fixed['centre'],fixed['fourth'],m*(w+p)/2,n*(z+q)/2):
    pos={**fixed,'third':t}
    if any(math.hypot(*v)>I['plate_radius']-1 for v in pos.values()):continue
    if any(dist(a,b)<.5 for a,b in itertools.combinations(pos.values(),2)):continue
    rs=[m*(w+2)/2,m*(p+2)/2,n*(z+2)/2,n*(q+2)/2,.06*82/2,.06*10/2,1.9]
    # subset geometry with matching global indexes
    fullrs=[0,0]+rs
    # test train without barrel; ignore dummy first two
    if not geom(pos,fullrs)[0:0] if False else False:pass
    valid=True
    for j in range(2,9):
     r=fullrs[j]; a=pos[owners[j]]; exc={owners[j]}
     for x,y in meshes:
      if x==j:exc.add(owners[y])
      if y==j:exc.add(owners[x])
     if math.hypot(*a)+r>I['plate_radius']-.3 or dist(a,bal['centre'])<r+bal['radius']+.1 or any(dist(a,b)<r+.25 for o,b in pos.items() if o not in exc):valid=False;break
    if not valid:continue
    for mb in mods:
     br=mb*83/2
