      if math.hypot(*b)>I['plate_radius']-1 or any(dist(b,pos[o])<.5 for o in fixed) or dist(b,t)<.5:continue
      if not geom(pos,radii):continue
      levels=color(pos,radii,N)
      if levels:
       teeth=[72,11,w,p,z,q,80,8]; modules=[mb,mb,m,m,n,n,.06,.06]
       D={'arbors':{'barrel':b,'third':t},'gears':{name:{'teeth':teeth[j],'module':modules[j],'level':levels[j]} for j,name in enumerate(names[:8])},'escape_wheel_level':levels[8]}
       json.dump(D,open('design.json','w'),indent=2);print('FOUND',N,D,flush=True);quit()
      del pos['barrel']
 print('none at',N,flush=True)
