 assert x['module']==y['module'] and x['level']==y['level']
 assert abs(math.dist(P[owners[a]],P[owners[b]])-x['module']*(x['teeth']+y['teeth'])/2)<=.005
assert Fraction(G['centre_wheel']['teeth'],G['third_pinion']['teeth'])*Fraction(G['third_wheel']['teeth'],G['fourth_pinion']['teeth'])==60
assert 60*Fraction(G['fourth_wheel']['teeth'],G['escape_pinion']['teeth'])==Fraction(I['beats_per_hour'],30)
ratio=Fraction(G['barrel_wheel']['teeth'],G['centre_pinion']['teeth']); reserve=Fraction(13,2)*ratio
assert ratio<=Fraction(str(I['max_barrel_ratio'])) and reserve>=I['power_reserve_target_h']
G['escape_wheel']={'radius':I['escape_wheel']['radius'],'level':D['escape_wheel_level']};owners['escape_wheel']='escape'
assert type(D['escape_wheel_level'])==int and 0<=D['escape_wheel_level']<=7
R={n:g.get('radius',g.get('module',0)*(g.get('teeth',0)+2)/2) for n,g in G.items()}
L={n:{g['level']} for n,g in G.items()};L['barrel_wheel'].add(G['barrel_wheel']['level']+1)
for p in P.values(): assert math.hypot(*p)<=I['plate_radius']-1
for a,b in itertools.combinations(P,2):assert math.dist(P[a],P[b])>=.5
margins=[]
for n,g in G.items():
 p=P[owners[n]];r=R[n]
 margins += [I['plate_radius']-.3-math.hypot(*p)-r,math.dist(p,I['balance']['centre'])-r-I['balance']['radius']-.1]
 exc={owners[n]}
 for a,b in M:
  if n==a:exc.add(owners[b])
  if n==b:exc.add(owners[a])
 for o,q in P.items():
  if o not in exc:margins.append(math.dist(p,q)-r-.25)
for a,b in itertools.combinations(G,2):
 if owners[a]==owners[b]:assert not L[a]&L[b]
 if L[a]&L[b] and (a,b) not in M and (b,a) not in M:margins.append(math.dist(P[owners[a]],P[owners[b]])-R[a]-R[b]-.1)
assert min(margins)>=-1e-9,min(margins)
